import hashlib,json,os,statistics,subprocess,time,platform
from pathlib import Path
r=Path(__file__).resolve().parent;cpu=min(os.sched_getaffinity(0));inputs=json.loads((r/'inputs.json').read_text())
loader=['taskset','-c',str(cpu),'/lib64/ld-linux-x86-64.so.2','--library-path','/lib/x86_64-linux-gnu:/usr/lib/x86_64-linux-gnu']
for p,h in json.loads((r/'hashes.json').read_text()).items(): assert hashlib.sha256((r/p).read_bytes()).hexdigest()==h,p
data=dict(metadata=dict(cpu=cpu,cpuinfo=Path('/proc/cpuinfo').read_text(),uname=platform.uname()._asdict(),start=time.time(),pairs=5,flags='GCC 15.3 -O3 -g'),large=[],tiny=[])
def save(): (r/'results.json').write_text(json.dumps(data,indent=2)+'\n')
def invoke(name,args,env):return json.loads(subprocess.check_output(loader+[str(r/name),*map(str,args)],env=env,text=True))
for points in (0,1):
 names=['baseline','fields']+(['points'] if points else [])
 for i,x in enumerate(inputs['large']):
  for context in (0,1):
   env=dict(os.environ)
   if context:env['SQ_REUSE_CONTEXT']='1'
   samples={n:[] for n in names}
   for pair in range(5):
    for n in (names if (pair+i)%2==0 else names[::-1]):
     samples[n].append(invoke(f'{n}-p{points}-capacity',[r/'grammars'/(x['grammar']+'.so'),x['symbol'],7,r/x['source']],env))
    for n in names:
     for k in ['hash','nodes','groups','capacity','retained_bytes']:assert samples[n][-1][k]==samples['baseline'][-1][k],(points,i,context,k)
   data['large'].append(dict(points=points,index=i,grammar=x['grammar'],context=context,samples=samples));save()
   med={n:statistics.median(v['median_ms'] for v in samples[n]) for n in names};print('large',points,i,x['grammar'],context,med,flush=True)
 for i,x in enumerate(inputs['tiny']):
  samples={n:[] for n in names}
  for pair in range(5):
   for n in (names if (pair+i)%2==0 else names[::-1]):
    samples[n].append(invoke(f'{n}-p{points}-tiny-layout',[r/'grammars'/(x['grammar']+'.so'),'tree_sitter_'+x['grammar'],7,*[r/f['path'] for f in x['files']]],os.environ))
   for n in names:
    for k in ['files','nodes','groups','slab_bytes','walk_checksum']:assert samples[n][-1][k]==samples['baseline'][-1][k]
    for k in samples[n][-1]['operations']:assert samples[n][-1]['operations'][k]['checksum']==samples['baseline'][-1]['operations'][k]['checksum']
  data['tiny'].append(dict(points=points,index=i,grammar=x['grammar'],bucket=x['bucket'],samples=samples));save();print('tiny',points,i,x['grammar'],flush=True)
data['metadata']['end']=time.time();save();print('COMPLETE',flush=True)

