  for k in ['files','nodes','groups','slab_bytes','walk_checksum']:assert samples['fields'][-1][k]==samples['scratch'][-1][k]
  for k in samples['fields'][-1]['operations']:assert samples['fields'][-1]['operations'][k]['checksum']==samples['scratch'][-1]['operations'][k]['checksum']
 data['tiny'].append(dict(points=1,index=i,grammar=x['grammar'],bucket=x['bucket'],samples=samples));save();print('tiny',i,x['grammar'],flush=True)
